-- =============================================================================
-- Stockify mono — seed catalogue / stock réaliste
-- Période mouvements : 2026-04-11 → 2026-07-11
-- Généré par : scripts/generate-realistic-seed.mjs
--
-- Prérequis : schéma migré, MySQL 8+
-- Usage :
--   mysql -uroot stockify_mono < seeds/realistic_catalog_seed.sql
--
-- Attention : vide les tables catalogue + stock (conserve users / refresh_tokens).
-- =============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION';

-- Purge inventory + catalog (ordre respectant les FKs)
DELETE FROM stock_lot_allocations;
DELETE FROM stock_movements;
DELETE FROM stock_lots;
DELETE FROM stock_policies;
DELETE FROM product_variants;
DELETE FROM products;
DELETE FROM product_categories;
DELETE FROM units_of_measure;

-- Keep FK checks off until the end for faster bulk load

